+        for (FType t : new ArrayList<FType>(parent.keySet())) {
+            FType r = root(t, parent);
+            List<FType> c = classes.get(r);
+            if (c == null) classes.put(r, c = new ArrayList<FType>());
+            c.add(t);
+        }
